def kth_smallest_matrix(matrix, k):
    n = len(matrix)
    low,high = matrix[0][0],matrix[-1][-1]
    while low < high:
        middle = (low+high)//2
        row,col,count = n-1,0,0
        while row >= 0 and col < n:
            if matrix[row][col] <= middle:
                count += row+1
                col += 1
            else:
                row -= 1
        if count >= k:
            high = middle
        else:
            low = middle+1
    return low

